        sys.exit(1)

    parts = stdin_data.split()
    if len(parts) < 2:
        sys.exit(1)

    cmd = parts[0]
    key = parts[1]

    if cmd == 'set':
        if len(parts) != 3:
            sys.exit(1)
        value = parts[2]
        store = load_encrypted_data('store.dat', passphrase)
        store[key] = value
        save_encrypted_data('store.dat', store, passphrase)
        sys.exit(0)
