import os
import sys
import base64
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
import json

def derive_key(passphrase: str) -> bytes:
    salt = os.urandom(16)
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000,
    )
    key = base64.urlsafe_b64encode(kdf.derive(passphrase.encode()))
    return key

def encrypt_data(data: str) -> str:
    key = derive_key(os.getenv('STORE_PASSPHRASE'))
    fernet = Fernet(key)
    return fernet.encrypt(data.encode()).decode()

def decrypt_data(encrypted_data: str) -> str:
    key = derive_key(os.getenv('STORE_PASSPHRASE'))
    fernet = Fernet(key)
    return fernet.decrypt(encrypted_data.encode()).decode()

def load_store() -> dict:
    if not os.path.exists('store.dat'):
        return {}
    with open('store.dat', 'rb') as f:
        encrypted_data = f.read().decode()
    return json.loads(decrypt_data(encrypted_data))

def save_store(store: dict):
    encrypted_data = encrypt_data(json.dumps(store))
    with open('store.dat', 'wb') as f:
        f.write(encrypted_data.encode())

def main():
