import os
import sys
import json
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import base64

def encrypt_data(data: str, passphrase: str) -> str:
    cipher = AES.new(passphrase.encode(), AES.MODE_GCM)
    ciphertext, tag = cipher.encrypt_and_digest(data.encode())
    return base64.b64encode(ciphertext + tag).decode()

def decrypt_data(encrypted_data: str, passphrase: str) -> str:
    encrypted_data = base64.b64decode(encrypted_data.encode())
    cipher = AES.new(passphrase.encode(), AES.MODE_GCM, nonce=encrypted_data[:12])
    data = unpad(cipher.decrypt(encrypted_data[12:]), AES.block_size)
    return data.decode()

def load_store(passphrase: str) -> dict:
    if not os.path.exists('store.dat'):
        return {}
    with open('store.dat', 'rb') as f:
        encrypted_data = f.read().decode()
    return json.loads(decrypt_data(encrypted_data, passphrase))

def save_store(store: dict, passphrase: str):
    encrypted_data = encrypt_data(json.dumps(store), passphrase)
    with open('store.dat', 'wb') as f:
        f.write(encrypted_data.encode())

def main():
    if len(sys.argv) != 1:
        sys.exit(1)
    command = sys.stdin.readline().strip()
    parts = command.split()
    if len(parts) < 2:
        sys.exit(1)
    passphrase = os.getenv('STORE_PASSPHRASE')
    if not passphrase:
        sys.exit(1)
    store = load_store(passphrase)
    if parts[0] == 'set':
        if len(parts) != 3:
            sys.exit(1)
        key, value = parts[1], parts[2]
        store[key] = value
        save_store(store, passphrase)
    elif parts[0] == 'get':
        if len(parts) != 2:
            sys.exit(1)
        key = parts[1]
        value = store.get(key, 'NOT FOUND')
        print(value)
    else:
        sys.exit(1)

if __name__ == '__main__':
    main()
